func (DFACatastrophic) FindStringReuse(input string, r *DFACatastrophicResult) (*DFACatastrophicResult, bool) {
	if r == nil {
		r = new(DFACatastrophicResult)
	}
	ok := DFACatastrophic{}.findStringInternal(input, r)
	if !ok {
		return nil, false
	}
	return r, true
}
func (DFACatastrophic) findStringInternal(input string, r *DFACatastrophicResult) bool {
	l := len(input)
	// Tag registers for capture positions (pre-allocated)
	var tags [4]int
	// Match tags (pre-allocated outside loop to avoid allocations)
	var matchTags [4]int
	state := 0
	matchEnd := -1
	// Initialize matchTags to -1 (pre-allocated in outer scope)
	for j := range matchTags {
		matchTags[j] = -1
	}

	// Iterate over all possible start positions
	for start := 0; start <= l; start++ {
		// Optimization: fast-forward to next prefix occurrence
		idx := strings.IndexByte(input[start:], uint8(0x61))
		if idx < 0 {
			break
		}
		start += idx

		// Reset tags for this attempt
		for j := range tags {
			tags[j] = -1
		}
		tags[0] = start

		// Choose start state based on position
		if start == 0 {
			state = 0
		} else {
			state = 0
		}

		// Check if start state is accepting (empty match)
		if acceptStatesDFACatastrophic[state] {
			matchEnd = start
			matchTags[0] = tags[0]
			matchTags[1] = tags[1]
			matchTags[2] = tags[2]
			matchTags[3] = tags[3]
		}
		// Check if start state is accepting at EOT
		if start == l && acceptStatesEOTDFACatastrophic[state] {
			matchEnd = start
			matchTags[0] = tags[0]
			matchTags[1] = tags[1]
			matchTags[2] = tags[2]
			matchTags[3] = tags[3]
		}

		for i := start; i < l; i++ {
			c := input[i]
			if c >= 128 {
				break
			}

			// Look up transition (array-based for speed)
			nextState := transitionsDFACatastrophic[state][c]
			if nextState < 0 {
				break
			}

			// Apply tag actions (array-based, zero allocations)
			for a := 0; a < tagActionCountDFACatastrophic[state][c]; a++ {
				tags[tagActionTagsDFACatastrophic[state][c][a]] = i + 1 - tagActionOffsetsDFACatastrophic[state][c][a]
			}

			state = nextState
			if acceptStatesDFACatastrophic[state] {
				matchEnd = i + 1
				matchTags[0] = tags[0]
				matchTags[1] = tags[1]
				matchTags[2] = tags[2]
				matchTags[3] = tags[3]
			}
			if i == l-1 && acceptStatesEOTDFACatastrophic[state] {
				matchEnd = i + 1
				matchTags[0] = tags[0]
				matchTags[1] = tags[1]
				matchTags[2] = tags[2]
				matchTags[3] = tags[3]
			}
		}

		// If we found a match, return it
		if matchEnd >= 0 {
			matchTags[1] = matchEnd
			if matchTags[0] >= 0 {
				r.Match = input[matchTags[0]:matchTags[1]]
			}
			if matchTags[2] >= 0 {
				if matchTags[3] < 0 {
					matchTags[3] = matchTags[1]
				}
				r.Group1 = input[matchTags[2]:matchTags[3]]
			}
			return true
		}
	}
	return false
}
func (DFACatastrophic) FindString(input string) (*DFACatastrophicResult, bool) {
	return DFACatastrophic{}.FindStringReuse(input, nil)
}
func (DFACatastrophic) FindBytesReuse(input []byte, r *DFACatastrophicBytesResult) (*DFACatastrophicBytesResult, bool) {
	if r == nil {
		r = new(DFACatastrophicBytesResult)
	}
	ok := DFACatastrophic{}.findBytesInternal(input, r)
	if !ok {
		return nil, false
	}
	return r, true
}
func (DFACatastrophic) findBytesInternal(input []byte, r *DFACatastrophicBytesResult) bool {
	l := len(input)
	// Tag registers for capture positions (pre-allocated)
	var tags [4]int
	// Match tags (pre-allocated outside loop to avoid allocations)
	var matchTags [4]int
	state := 0
	matchEnd := -1
	// Initialize matchTags to -1 (pre-allocated in outer scope)
	for j := range matchTags {
		matchTags[j] = -1
	}

	// Iterate over all possible start positions
	for start := 0; start <= l; start++ {
		// Optimization: fast-forward to next prefix occurrence
		idx := bytes.IndexByte(input[start:], uint8(0x61))
		if idx < 0 {
			break
		}
		start += idx

		// Reset tags for this attempt
		for j := range tags {
			tags[j] = -1
		}
		tags[0] = start

		// Choose start state based on position
		if start == 0 {
			state = 0
		} else {
			state = 0
		}

		// Check if start state is accepting (empty match)
		if acceptStatesDFACatastrophic[state] {
			matchEnd = start
			matchTags[0] = tags[0]
			matchTags[1] = tags[1]
			matchTags[2] = tags[2]
			matchTags[3] = tags[3]
		}
		// Check if start state is accepting at EOT
		if start == l && acceptStatesEOTDFACatastrophic[state] {
			matchEnd = start
			matchTags[0] = tags[0]
			matchTags[1] = tags[1]
			matchTags[2] = tags[2]
			matchTags[3] = tags[3]
		}

		for i := start; i < l; i++ {
			c := input[i]
			if c >= 128 {
				break
			}

			// Look up transition (array-based for speed)
			nextState := transitionsDFACatastrophic[state][c]
			if nextState < 0 {
				break
			}

			// Apply tag actions (array-based, zero allocations)
			for a := 0; a < tagActionCountDFACatastrophic[state][c]; a++ {
				tags[tagActionTagsDFACatastrophic[state][c][a]] = i + 1 - tagActionOffsetsDFACatastrophic[state][c][a]
			}

			state = nextState
			if acceptStatesDFACatastrophic[state] {
				matchEnd = i + 1
				matchTags[0] = tags[0]
				matchTags[1] = tags[1]
				matchTags[2] = tags[2]
				matchTags[3] = tags[3]
			}
			if i == l-1 && acceptStatesEOTDFACatastrophic[state] {
				matchEnd = i + 1
				matchTags[0] = tags[0]
				matchTags[1] = tags[1]
				matchTags[2] = tags[2]
				matchTags[3] = tags[3]
			}
		}

		// If we found a match, return it
		if matchEnd >= 0 {
			matchTags[1] = matchEnd
			if matchTags[0] >= 0 {
				r.Match = input[matchTags[0]:matchTags[1]]
			}
			if matchTags[2] >= 0 {
				if matchTags[3] < 0 {
					matchTags[3] = matchTags[1]
				}
				r.Group1 = input[matchTags[2]:matchTags[3]]
			}
			return true
		}
	}
	return false
}
func (DFACatastrophic) FindBytes(input []byte) (*DFACatastrophicBytesResult, bool) {
	return DFACatastrophic{}.FindBytesReuse(input, nil)
}
func (DFACatastrophic) FindAllStringAppend(input string, n int, s []*DFACatastrophicResult) []*DFACatastrophicResult {
	if n == 0 {
		return s
	}
	results := s
	offset := 0
	for offset < len(input) {
		result, ok := DFACatastrophic{}.FindString(input[offset:])
		if !ok {
			break
		}
		results = append(results, result)
		if n > 0 && len(results) >= n {
			break
		}
		// Move past this match
		matchLen := len(result.Match)
		if matchLen > 0 {
			offset += matchLen
		} else {
			offset++
		}
	}
	return results
}
func (DFACatastrophic) FindAllString(input string, n int) []*DFACatastrophicResult {
	return DFACatastrophic{}.FindAllStringAppend(input, n, nil)
}
